      validResponse: {result: 'sunny'},
      result: expect.stringMatching(/postalCode.*required|required.*postalCode/i),
      executorCalls: 1,
    });
  });

  it('rejects a type mismatch declared through a local schema reference', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn<() => Promise<string>>().mockResolvedValue('unreachable');
    registry.register(
      {
        name: 'referenced_email',
        description: 'Requires a referenced email schema',
        inputSchema: {
          type: 'object',
          properties: {email: {$ref: '#/$defs/email'}},
          required: ['email'],
          $defs: {email: {type: 'string'}},
        },
      },
      executor
    );

    const response = await registry.execute('referenced_email', {email: 42});
    const executorCallCount = executor.mock.calls.length;

    expect({result: response.result, executorCalls: executorCallCount}).toEqual({
      result: expect.stringMatching(/email.*string/i),
      executorCalls: 0,
    });
  });
