import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: Validator;
}

type Validator = ValidateFunction;

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly schemaValidator = new Ajv({strict: false, validateFormats: false} as never);
  private readonly dynamicValidators = new WeakMap<Record<string, unknown>, Validator>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validator = typeof definition === 'function' ? undefined : this.compileStaticSchema(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  private compileStaticSchema(definition: ToolDefinition): Validator {
    try {
      this.assertValidSchema(definition.inputSchema);
      return this.schemaValidator.compile(validationSchema(definition.inputSchema));
    } catch (error) {
      const reason = error instanceof Error ? error.message : 'unknown schema error';
      throw new Error(`Invalid input schema for tool ${definition.name}: ${reason}`, {cause: error});
    }
  }

  private getValidator(tool: StoredTool, definition: ToolDefinition): Validator {
    if (tool.validator) return tool.validator;
    const cached = this.dynamicValidators.get(definition.inputSchema);
    if (cached) return cached;
    this.assertValidSchema(definition.inputSchema);
    const validator = this.schemaValidator.compile(validationSchema(definition.inputSchema));
    this.dynamicValidators.set(definition.inputSchema, validator);
    return validator;
  }

  private assertValidSchema(schema: Record<string, unknown>): void {
    const validator = this.schemaValidator as {
      validateSchema?: (candidate: Record<string, unknown>) => boolean;
      errors?: unknown[] | null;
    };
    if (validator.validateSchema && !validator.validateSchema(schema)) {
      throw new Error(schemaErrorMessage(firstSchemaError(validator.errors)));
    }
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates tool input before execution; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = this.getValidator(tool, definition);
    if (!validate(input)) {
      return {result: `Invalid tool input: ${describeSchemaError(validate.errors?.[0])}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

function firstSchemaError(errors: unknown[] | null | undefined): unknown {
  return errors?.[0];
}

function schemaErrorMessage(error: unknown): string {
  return isRecord(error) && typeof error.message === 'string' ? error.message : 'schema is invalid';
}

function describeSchemaError(error: unknown): string {
  if (!isRecord(error)) return 'input failed schema validation';
  const params = isRecord(error.params) ? error.params : {};
  const instancePath =
    typeof error.instancePath === 'string' && error.instancePath.length > 0
      ? error.instancePath
      : typeof error.dataPath === 'string'
        ? error.dataPath
        : '';
  const path = instancePath.replace(/^[/.]/, '');
  const property =
    error.keyword === 'required' && typeof params.missingProperty === 'string'
      ? [path, params.missingProperty].filter(Boolean).join('.')
      : path || 'input';
  const message = typeof error.message === 'string' ? error.message : 'failed schema validation';
  return `${property} ${message}`;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function validationSchema(schema: Record<string, unknown>): Record<string, unknown> {
  const filtered: Record<string, unknown> = {};
  for (const keyword of ['$ref', 'type', 'enum', 'required']) {
    if (keyword in schema) filtered[keyword] = schema[keyword];
  }
  if (isRecord(schema.$defs)) {
    filtered.$defs = Object.fromEntries(
      Object.entries(schema.$defs).map(([name, definition]) => [
        name,
        isRecord(definition) ? validationSchema(definition) : definition,
      ])
    );
